{
  "aktywnosci": [
    {
      "tytul": "Kuferek dobrych słów – zabawa słowna w kręgu",
      "opis": "Nauczyciel siada z dziećmi w kręgu i kładzie na środku ozdobne pudełko oraz podaje dzieciom miękkie, materiałowe serduszko. Przedszkolaki przekazują sobie serce z rąk do rąk i kończą zdanie: „Moja mama jest wspaniała, bo…”. Nauczyciel zapisuje najciekawsze wypowiedzi na kolorowych karteczkach i symbolicznie chowa je do kuferka dobrych życzeń."
    },
    {
      "tytul": "Taniec radości dla mamy – zabawa muzyczno-ruchowa z szarfami",
      "opis": "Dzieci otrzymują kolorowe szarfy lub chustki i swobodnie tańczą po sali przy radosnej muzyce, ilustrując ruchami uśmiech i energię. Na przerwę w muzyce nauczyciel podaje hasło (np. „przytulenie”, „promyk słońca”, „bicie serca”), a dzieci zatrzymują się i tworzą z szarf odpowiedni kształt na dywanie lub przytulają się w parach. Na zakończenie cała grupa wspólnie układa z szarf jedno wielkie, uśmiechnięte serce."
    },
    {
      "tytul": "Bukiet uśmiechów – praca plastyczna z odbijaniem dłoni",
      "opis": "Dzieci przygotowują na kartkach papieru kompozycję z kolorowych odcisków własnych dłoni pomalowanych farbami plakatowymi, które tworzą płatki kwiatów. Za pomocą pędzli i kredek dorysowują łodygi oraz uśmiechnięte buzie wewnątrz każdego kwiatka. Nauczyciel pomaga podpisać prace i zawiesza je na tablicy jako świąteczną galerię dla mam."
    }
  ]
}
